const src = $('Telegram Trigger').first().json.message ?? {};
const text = String(src.text ?? '').trim();
const fromId = String(src.from?.id ?? '');
const chatId = String(src.chat?.id ?? '');
const messageId = String(src.message_id ?? '');
const settingsRows = $('Read Settings').all().map(x => x.json);
const settings = Object.fromEntries(settingsRows.map(r => [String(r.key || '').trim(), r.value]));
const tz = String(settings.timezone || 'Asia/Gaza');
const fmt = new Intl.DateTimeFormat('en-CA', {timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'});
const expenseDate = fmt.format(new Date());
const monthKey = expenseDate.slice(0,7);
const categories = $('Read Categories').all().map(x => x.json).filter(r => {
  const v = String(r.enabled ?? 'TRUE').trim().toLowerCase();
  return ['true','1','yes','نعم'].includes(v);
});
let raw = $('AI Agent - Understand Palestinian Arabic').first().json.output ?? $('AI Agent - Understand Palestinian Arabic').first().json.text ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
let parsed = null;
try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }

const reportActions = ['report_day','today','report_week','week','report_month','month'];
const common = {text,fromId,chatId,messageId,expenseDate,monthKey,authorizedUserId:String(settings.authorized_telegram_user_id || '').trim(),budget:Number(settings.monthly_budget_ils || 300),currency:String(settings.currency || 'ILS'),thresholdPercent:Number(settings.budget_alert_threshold_percent || 100),timezone:tz,weeklyReportEnabled:String(settings.weekly_report_enabled ?? 'true').toLowerCase() !== 'false',monthlyReportEnabled:String(settings.monthly_report_enabled ?? 'true').toLowerCase() !== 'false'};

// ---- helpers: robust amount parsing + regex fallback ----
const toLatin = s => String(s ?? '')
  .replace(/[\u0660-\u0669]/g, d => String(d.charCodeAt(0) - 0x0660))
  .replace(/[\u06F0-\u06F9]/g, d => String(d.charCodeAt(0) - 0x06F0))
  .replace(/\u066B/g, '.');
const parseAmount = v => {
  if (typeof v === 'number') return Number.isFinite(v) ? v : NaN;
  const m = toLatin(v).match(/\d+(?:\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};
function cleanItem(s) {
  const stop = /(^|\s)(?:جبت|اشتريت|شريت|دفعت|صرفت|حطيت|شيكل|شيكلات|ش|ILS|NIS|و|ب|بـ|ل)(?=\s|$)/gi;
  return String(s || '').replace(/[،,;؛:+\-]+/g, ' ').replace(stop, ' ').replace(stop, ' ').replace(/\s+/g, ' ').trim();
}
function regexExpenses(input) {
  let t = toLatin(input).replace(/\n/g, ' ، ').trim();
  t = t.replace(/^\s*(?:جبت|اشتريت|شريت|دفعت|صرفت)\s+/, '');
  const out = [];
  let m;
  if (/^\d/.test(t)) {
    const re = /(\d+(?:\.\d+)?)\s*([^\d]*)/g;
    while ((m = re.exec(t))) {
      const item = cleanItem(m[2]); const amount = Number(m[1]);
      if (item && amount > 0) out.push({ item, amount, category: '' });
    }
  } else {
    const re = /([^\d]+?)\s*(\d+(?:\.\d+)?)/g;
    while ((m = re.exec(t))) {
      const item = cleanItem(m[1]); const amount = Number(m[2]);
      if (item && amount > 0) out.push({ item, amount, category: '' });
    }
  }
  return out;
}

let action = parsed ? String(parsed.action || 'unknown').trim() : 'unknown';
let sourceExpenses = (parsed && Array.isArray(parsed.expenses) ? parsed.expenses : [])
  .map(e => ({ ...e, item: String(e?.item ?? '').trim(), amount: parseAmount(e?.amount) }));
const aiOk = action === 'expense' && sourceExpenses.length > 0 && sourceExpenses.every(e => e.item.length > 0 && Number.isFinite(e.amount) && e.amount > 0);
const hasDigit = /[0-9\u0660-\u0669\u06F0-\u06F9]/.test(text);
let usedFallback = false;
if (!aiOk && !reportActions.includes(action) && action !== 'help' && hasDigit) {
  const fb = regexExpenses(text);
  if (fb.length > 0) { action = 'expense'; sourceExpenses = fb; usedFallback = true; }
}

if (!parsed && !usedFallback) {
  return [{json:{...common,action:'unknown',expenses:[],valid:false,reply:'مش قادر أفهم الرسالة بشكل موثوق. جرّب: جبت بطاقة نت ب 2'}}];
}
const clarification = parsed ? String(parsed.clarification || '') : '';
if (action !== 'expense' || sourceExpenses.length === 0) {
 let reply = clarification;
 if (action === 'help') reply = 'أرسل مصروفًا مثل: جبت بطاقة نت ب 2. ويمكنك كتابة عدة مصاريف برسالة واحدة مثل: قهوة ب 5 ومناقيش ب 8. وللتراجع عن آخر تسجيل اكتب: تراجع';
 else if (reportActions.includes(action)) reply = '';
 else if (!reply) reply = 'ما ظهر عندي مصروف بمبلغ واضح. جرّب مثلًا: جبت بطاقة نت ب 2.';
 const normalizedAction = reportActions.includes(action) ? action : (action === 'help' ? 'help' : 'unknown');
 return [{json:{...common,action:normalizedAction,expenses:[],valid:false,reply,clarification}}];
}
function categoryFor(e) {
  const item = String(e?.item || '').trim().toLowerCase();
  const proposed = String(e?.category || '').trim();
  for (const c of categories) {
   const keys = String(c.keywords || '').split(/[،,;；]/).map(k=>k.trim().toLowerCase()).filter(Boolean);
   if (keys.some(k => item.includes(k))) return String(c.category_name || 'غير مصنف').trim();
  }
  const exact = categories.find(c => String(c.category_name || '').trim() === proposed);
  if (exact) return String(exact.category_name).trim();
  const fallback = categories.find(c => String(c.category_name || '').trim() === 'غير مصنف') || categories.find(c => String(c.category_name || '').trim() === 'أخرى');
  return String(fallback?.category_name || 'غير مصنف').trim();
}
const expenses = sourceExpenses.map((e,i)=>{
 const item=String(e?.item || '').trim(); const amount=Number(e?.amount); const category=categoryFor(e);
 const valid=item.length>0 && Number.isFinite(amount) && amount>0;
 return {item,amount:valid?amount:null,category,valid,expenseIndex:i+1,expenseCount:sourceExpenses.length};
});
return [{json:{...common,action:'expense',expenses,valid:expenses.some(e=>e.valid),reply:'',usedFallback}}];

const p = $('Parse Message').first().json;
const rows = $input.all().map(x => x.json);
const active = rows.filter(r =>
  String(r.status || 'active').trim() === 'active' &&
  String(r.month_key || '').slice(0, 7) === p.monthKey
);
const currentTotal = active.reduce((sum, r) => sum + Number(r.amount_ils || r.amount || 0), 0);

const expenses = Array.isArray(p.expenses) ? p.expenses : [];
const toSave = [];
const duplicates = [];
const invalid = [];

for (const e of expenses) {
  if (!e.valid || !e.item || !Number.isFinite(Number(e.amount)) || Number(e.amount) <= 0) {
    invalid.push(e);
    continue;
  }

  const expenseId = `m-${p.fromId}-${p.messageId}-${e.expenseIndex}`;
  const duplicate = rows.some(r => String(r.expense_id || '') === expenseId);
  if (duplicate) {
    duplicates.push(e);
    continue;
  }

  toSave.push({
    ...p,
    ...e,
    expense_id: expenseId,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    status: 'active'
  });
}

if (toSave.length === 0) {
  let reply;
  if (duplicates.length > 0 && invalid.length === 0) {
    reply = '⚠️ هذه المصاريف مسجلة من قبل، فما كررتها.';
  } else {
    reply = 'ما قدرت أسجل أي مصروف؛ تأكد إن كل غرض معه مبلغ واضح. مثال: قهوة ب 5 ومناقيش ب 8.';
  }
  return [{ json: { ...p, ok: false, reply } }];
}

const newTotal = toSave.reduce((sum, e) => sum + Number(e.amount), 0);
const totalAfter = currentTotal + newTotal;
const budget = Number(p.budget || 300);
const remaining = budget - totalAfter;
const cur = p.currency || 'ILS';
const fmtN = v => Number.isInteger(v) ? String(v) : v.toFixed(2);

// ---- where the money goes this month (existing + new) ----
const catTotals = {};
const itemTotals = {};
const addTo = (map, key, amt) => { const k = String(key || '').trim(); if (!k) return; map[k] = (map[k] || 0) + amt; };
for (const r of active) {
  const amt = Number(r.amount_ils || r.amount || 0);
  addTo(catTotals, r.category || 'أخرى', amt);
  addTo(itemTotals, r.item, amt);
}
for (const e of toSave) {
  const amt = Number(e.amount);
  addTo(catTotals, e.category || 'أخرى', amt);
  addTo(itemTotals, e.item, amt);
}
const topCats = Object.entries(catTotals).sort((a, b) => b[1] - a[1]).slice(0, 3);
const topItem = Object.entries(itemTotals).sort((a, b) => b[1] - a[1])[0];
const medals = ['🥇', '🥈', '🥉'];

const lines = [
  '✅ تم تسجيل المصروفات بنجاح!',
  `📌 عدد المصاريف الجديدة: ${toSave.length}`,
  ...toSave.map(e => `🛍️ ${e.item} (${e.category}): ${e.amount} ${cur}`),
  `💵 مجموع المصاريف الجديدة: ${newTotal} ${cur}`,
  `📊 مصاريف الشهر: ${totalAfter} ${cur}`,
  `💰 الميزانية: ${budget} ${cur}`,
  remaining >= 0
    ? `🟢 ضايلك: ${remaining} ${cur}`
    : `🔴 متجاوز الميزانية بـ ${Math.abs(remaining)} ${cur}`
];

if (topCats.length) {
  lines.push('', '📈 وين بتروح مصاريفك هالشهر:');
  topCats.forEach(([c, v], i) => {
    const pct = totalAfter > 0 ? Math.round(v / totalAfter * 100) : 0;
    lines.push(`${medals[i]} ${c}: ${fmtN(v)} ${cur} (${pct}%)`);
  });
  if (topItem) lines.push(`🔝 أكثر غرض بتصرف عليه: ${topItem[0]} (${fmtN(topItem[1])} ${cur})`);
}

if (duplicates.length) {
  lines.push(`⚠️ تم تجاهل ${duplicates.length} مصروف مكرر.`);
}
if (invalid.length) {
  lines.push(`⚠️ تم تجاهل ${invalid.length} مصروف غير واضح.`);
}
lines.push('', '↩️ للتراجع عن هذا التسجيل اكتب: تراجع');

const reply = lines.join('\n');
return toSave.map(e => ({
  json: {
    ...e,
    ok: true,
    total_after: totalAfter,
    new_total: newTotal,
    reply
  }
}));

const p = $('Validate and Calculate').first().json;
return [{
  json: {
    chatId: p.chatId,
    reply: p.reply,
    monthKey: p.monthKey,
    totalAfter: Number(p.total_after || 0),
    budget: Number(p.budget || 300), thresholdPercent: Number(p.thresholdPercent || 100), currency: p.currency || 'ILS'
  }
}];

