const u = $json;

const msg = u.message || u.callback_query?.message || {};
const cb = u.callback_query || null;

const text = String(msg.text || '').trim();
const callback = String(cb?.data || '').trim();

const fromId = String(
  (u.message?.from || cb?.from || {}).id || ''
);

const chatId = String(msg.chat?.id || '');

const isSlashControl =
  /^\/(settings|menu|budget|currency|threshold|weekly|monthly|category_add|categoryadd|category_name|categoryname|category_keywords|categorykeywords|category_toggle|categorytoggle|categories|help)(?:@\w+)?(?:\s|$)/i.test(text);

const isNaturalCategoryAdd =
  /^(?:حط|ضيف|أضف|اضف)\s+تصنيف(?:\s+جديد)?(?:\s|$)/i.test(text);

const isNaturalCurrencyChange =
  /^(?:عدل|عدّل|غيّر|غير|تغيير|اجعل|خلي|خلّي)\s+العملة(?:\s+(?:(?:الى|إلى)\s+)?)/i.test(text);

const isNaturalThresholdChange =
  /^(?:غيّر|غير|عدل|عدّل|تغيير)\s+(?:حد|نسبة)\s+التنبيه(?:\s|$)/i.test(text);

const isNaturalBudgetChange =
  /^(?:ارفع|رفع|زِد|زيد|نزل|نزّل|خفّض|خفض|قلل|قلّل|غيّر|غير|عدل|عدّل|تغيير)\s+الميزانية(?:\s|$)/i.test(text) ||
  /^(?:خلّي|خلي|اجعل)\s+(?:الميزانية|ميزانيتي)(?:\s|$)/i.test(text);

const isControl =
  Boolean(cb) ||
  isSlashControl ||
  isNaturalCategoryAdd ||
  isNaturalCurrencyChange ||
  isNaturalThresholdChange ||
  isNaturalBudgetChange;

return [
  {
    json: {
      ...u,
      _control: {
        isControl,
        text,
        callback,
        fromId,
        chatId,
        messageId: String(msg.message_id || ''),
        callbackQueryId: String(cb?.id || '')
      }
    }
  }
];

const ctl = $('Control Router').first().json._control;

const settings = Object.fromEntries(
  $('Read Settings for Control').all().map(x => [
    String(x.json.key || '').trim(),
    String(x.json.value ?? '').trim()
  ])
);

const clean = v => String(v ?? '')
  .replace(/[\u200B-\u200D\uFEFF]/g, '')
  .replace(/\\/g, '')
  .trim();

const normalizeId = v => clean(v).toUpperCase();

const allCats = $('Read Categories for Control')
  .all()
  .map(x => x.json)
  .filter(x => clean(x.category_id));

const cats = [
  ...new Map(
    allCats.map(c => [
      normalizeId(c.category_id),
      {
        ...c,
        category_id: normalizeId(c.category_id)
      }
    ])
  ).values()
];

let raw = clean(ctl.callback || ctl.text || '');
const cb = ctl.callback;

let op = 'help';
let key = '';
let value = '';
let description = '';
let category_id = '';
let category_name = '';
let keywords = '';
let enabled = 'TRUE';
let reply = '';

const configuredAuthorizedId = clean(
  settings.authorized_telegram_user_id || ''
);

const authorizedId =
  (!configuredAuthorizedId ||
   configuredAuthorizedId.includes('REPLACE_WITH'))
    ? ''
    : configuredAuthorizedId;

if (!authorizedId || String(ctl.fromId || '').trim() !== authorizedId) {
  return [{
    json: {
      ...ctl,
      op: 'help',
      reply: 'عذرًا، هذا البوت خاص بصاحبه وما عندك صلاحية تستخدمه.'
    }
  }];
}

// ================================
// العملات العربية
// ================================

const currencyMap = {
  'دولار': 'USD',
  'الدولار': 'USD',
  'دولار امريكي': 'USD',
  'الدولار امريكي': 'USD',
  'دولار أمريكي': 'USD',
  'الدولار الأمريكي': 'USD',
  'usd': 'USD',

  'شيكل': 'ILS',
  'الشيكل': 'ILS',
  'شيكل جديد': 'ILS',
  'الشيكل الجديد': 'ILS',
  'ils': 'ILS',

  'دينار': 'JOD',
  'الدينار': 'JOD',
  'دينار اردني': 'JOD',
  'دينار أردني': 'JOD',
  'الدينار الأردني': 'JOD',
  'jod': 'JOD',

  'يورو': 'EUR',
  'اليورو': 'EUR',
  'eur': 'EUR'
};

function normalizeCurrency(input) {
  const text = clean(input)
    .replace(/[.!،,؛;]+$/g, '')
    .trim();

  return currencyMap[text] ||
    currencyMap[text.toLowerCase()] ||
    text.toUpperCase();
}

// ================================
// تحويل اللغة الطبيعية إلى أوامر
// ================================

if (!cb) {
  // تغيير العملة:
  // اجعل العملة شيكل
  // خلي العملة شيكل
  // عدل العملة شيكل
  // غير العملة إلى دولار
  const currencyMatch = raw.match(
    /^(?:عدل|عدّل|غيّر|غير|تغيير|اجعل|خلي|خلّي)\s+العملة\s*(?:(?:الى|إلى|لـ)\s*)?(.+?)\s*$/i
  );

  if (currencyMatch) {
    const currencyText = clean(currencyMatch[1]);

    if (!currencyText) {
      raw = '/__invalid_natural_currency';
    } else {
      raw = '/currency ' + normalizeCurrency(currencyText);
    }
  }

  // تغيير حد التنبيه
  const thresholdMatch = raw.match(
    /^(?:غيّر|غير|عدل|عدّل|تغيير)\s+(?:حد|نسبة)\s+التنبيه\s*(?:(?:الى|إلى)\s*)?(\d+(?:\.\d+)?)\s*%?\s*$/i
  );

  if (thresholdMatch) {
    raw = '/threshold ' + thresholdMatch[1];
  } else if (
    /^(?:غيّر|غير|عدل|عدّل|تغيير)\s+(?:حد|نسبة)\s+التنبيه(?:\s|$)/i.test(raw)
  ) {
    raw = '/__invalid_natural_threshold';
  }

  // تغيير الميزانية
  const budgetPatterns = [
    /^(?:ارفع|رفع|زِد|زيد|نزل|نزّل|خفّض|خفض|قلل|قلّل|غيّر|غير|عدل|عدّل|تغيير)\s+الميزانية\s*(?:(?:الى|إلى)\s*)?(\d+(?:\.\d+)?)\s*$/i,
    /^(?:خلّي|خلي|اجعل)\s+(?:الميزانية|ميزانيتي)\s*(?:(?:الى|إلى)\s*)?(\d+(?:\.\d+)?)\s*$/i
  ];

  let budgetMatch = null;

  for (const pattern of budgetPatterns) {
    budgetMatch = raw.match(pattern);
    if (budgetMatch) break;
  }

  if (budgetMatch) {
    raw = '/budget ' + budgetMatch[1];
  } else if (
    /^(?:ارفع|رفع|زِد|زيد|نزل|نزّل|خفّض|خفض|قلل|قلّل|غيّر|غير|عدل|عدّل|تغيير)\s+الميزانية(?:\s|$)/i.test(raw) ||
    /^(?:خلّي|خلي|اجعل)\s+(?:الميزانية|ميزانيتي)(?:\s|$)/i.test(raw)
  ) {
    raw = '/__invalid_natural_budget';
  }

  // إضافة تصنيف باللغة الطبيعية
  // مثال:
  // ضيف تصنيف جديد اسمه مواصلات والكلمات المفتاحية لها تكسي، باص
  // أو:
  // ضيف تصنيف مواصلات | تكسي، باص
  if (
    /^(?:حط|ضيف|أضف|اضف)\s+تصنيف(?:\s+جديد)?(?:\s|$)/i.test(raw)
  ) {
    const naturalText = clean(raw);

    let parsedName = '';
    let parsedKeywords = '';

    if (naturalText.includes('|')) {
      const parts = naturalText.split('|').map(clean);

      if (parts.length >= 2) {
        parsedName = parts[0]
          .replace(
            /^(?:حط|ضيف|أضف|اضف)\s+تصنيف(?:\s+جديد)?\s*/i,
            ''
          )
          .replace(/^(?:اسمه|اسمها|اسم)\s*/i, '')
          .trim();

        parsedKeywords = parts.slice(1).join(' | ');
      }
    } else {
    const nameMatch = naturalText.match(
  /(?:اسمه|اسمها|اسم)\s+(.+?)(?=\s+(?:و?الكلمات\s+المفتاحية|والكلمات|المفتاحية|كلمات(?:\s+مفتاحية)?)|$)/i
);

     const kwMatch = naturalText.match(
  /(?:الكلمات\s+المفتاحية|كلمات\s+مفتاحية|الكلمات|المفتاحية)\s+(?:(?:لها|له|للتصنيف)\s*)?(?:هي\s*)?[:：=]?\s*(.+)$/i
);

      if (nameMatch && kwMatch) {
        parsedName = nameMatch[1];
        parsedKeywords = kwMatch[1];
      }
    }

    parsedName = clean(parsedName)
      .replace(/[،,;؛|]+$/, '')
      .trim();

    parsedKeywords = clean(parsedKeywords)
      .replace(/^[\s:：=]+/, '')
      .replace(/[\\]+$/g, '')
      .trim();

    if (parsedName && parsedKeywords) {
      raw = '/category_add ' +
        parsedName + ' | ' + parsedKeywords;
    } else {
      raw = '/__invalid_natural_category';
    }
  }

  // تعديل اسم تصنيف
  // غير اسم التصنيف C11 إلى مواصلات
  const nameChange = raw.match(
    /^(?:غير|غيّر|عدل|عدّل)\s+اسم\s+التصنيف\s+(C\d+)\s+(?:الى|إلى)\s+(.+)$/i
  );

  if (nameChange) {
    raw = '/category_name ' +
      nameChange[1] + ' | ' + clean(nameChange[2]);
  }

  // تعديل الكلمات المفتاحية
  // عدل كلمات التصنيف C11 إلى تكسي، باص
  const keywordsChange = raw.match(
    /^(?:غير|غيّر|عدل|عدّل)\s+(?:كلمات|الكلمات)\s+(?:المفتاحية\s+)?(?:للتصنيف\s+)?(C\d+)\s+(?:الى|إلى)\s+(.+)$/i
  );

  if (keywordsChange) {
    raw = '/category_keywords ' +
      keywordsChange[1] + ' | ' + clean(keywordsChange[2]);
  }

  // تفعيل أو تعطيل تصنيف
  const categoryToggle = raw.match(
    /^(?:فعّل|فعل|تفعيل|شغّل|شغل|عطّل|عطل|تعطيل)\s+(?:التصنيف\s+)?(C\d+)\s*$/i
  );

  if (categoryToggle) {
    const action = clean(raw).split(/\s+/)[0];

    const turnOn = [
      'فعّل', 'فعل', 'تفعيل', 'شغّل', 'شغل'
    ].includes(action);

    raw = '/category_toggle ' +
      categoryToggle[1] + (turnOn ? ' on' : ' off');
  }
}

// ================================
// رد قائمة التصنيفات
// ================================

function categoriesReply() {
  const isActive = c =>
    ![
      'false', '0', 'no', 'off', 'معطل', 'معطّل'
    ].includes(clean(c.enabled ?? 'TRUE').toLowerCase());

  const lines = [
    '🏷️ تصنيفات مصروفي',
    '📊 العدد: ' + cats.length,
    ''
  ];

  for (const c of cats) {
    lines.push(
      (isActive(c) ? '🟢 ' : '⚪ ') +
      c.category_id + ' — ' +
      clean(c.category_name || 'بدون اسم') +
      (isActive(c) ? ' (مفعّل)' : ' (معطّل)')
    );
  }

  return lines.join('\n');
}

function parseKeywords(text) {
  return clean(text)
    .replace(/\s*[,،;؛]\s*/g, ', ')
    .trim();
}

function helpReply() {
  return [
    '⚙️ إعدادات مصروفي',
    '',
    '💰 الميزانية: ' +
      (settings.monthly_budget_ils || '300'),
    '💱 العملة: ' +
      (settings.currency || 'ILS'),
    '🔔 نسبة التنبيه: ' +
      (settings.budget_alert_threshold_percent || '100') + '%',
    '📅 التقرير الأسبوعي: ' +
      (settings.weekly_report_enabled || 'true'),
    '🗓️ التقرير الشهري: ' +
      (settings.monthly_report_enabled || 'true'),
    '',
    '💰 الميزانية:',
    '/budget 500',
    'ارفع الميزانية إلى 600',
    'خلي الميزانية 400',
    'نزل الميزانية إلى 300',
    '',
    '💱 العملة:',
    '/currency ILS',
    'اجعل العملة شيكل',
    'خلي العملة دولار',
    'عدل العملة دينار',
    '',
    '🔔 التنبيه والتقارير:',
    '/threshold 80',
    '/weekly on',
    '/weekly off',
    '/monthly on',
    '/monthly off',
    '',
    '🏷️ التصنيفات:',
    '/categories',
    '/category_add مواصلات | تكسي، باص',
    '/category_name C11 | الاسم الجديد',
    '/category_keywords C11 | كلمة1، كلمة2',
    '/category_toggle C11 off',
    '',
    'أمثلة باللغة الطبيعية:',
     'حط تصنيف جديد اسمه مواصلات والكلمات المفتاحية لها تكسي، باص',
    'ضيف تصنيف جديد اسمه مواصلات والكلمات المفتاحية لها تكسي، باص',
    'غير اسم التصنيف C11 إلى مواصلات',
    'عدل كلمات التصنيف C11 إلى تكسي، باص',
    'عطّل التصنيف C11',
    'فعّل التصنيف C11'
  ].join('\n');
}

// ================================
// تحليل الأوامر
// ================================

if (cb) {
  const act = cb.replace(/^control:/, '');

  if (act === 'menu' || act === 'settings') {
    op = 'menu';
    reply = helpReply();

  } else if (act === 'categories') {
    op = 'categories';
    reply = categoriesReply();

  } else {
    op = 'help';

    const instructions = {
      budget: 'لتغيير الميزانية أرسل: /budget 500',
      currency: 'لتغيير العملة أرسل: /currency ILS',
      threshold: 'لتغيير نسبة التنبيه أرسل: /threshold 80',
      weekly: 'استخدم /weekly on أو /weekly off',
      monthly: 'استخدم /monthly on أو /monthly off'
    };

    reply = instructions[act] ||
      'أرسل الأمر مع القيمة المطلوبة.';
  }

} else {
  const m = raw.match(
    /^\/(settings|menu|help|budget|currency|threshold|weekly|monthly|category_add|categoryadd|category_name|categoryname|category_keywords|categorykeywords|category_toggle|categorytoggle|categories)(?:@\w+)?(?:\s+(.*))?$/i
  );

  let command = (m?.[1] || '').toLowerCase();
  const arg = (m?.[2] || '').trim();

  const aliases = {
    categoryadd: 'category_add',
    categoryname: 'category_name',
    categorykeywords: 'category_keywords',
    categorytoggle: 'category_toggle'
  };

  command = aliases[command] || command;

  if (raw === '/__invalid_natural_budget') {
    reply =
      '⚠️ لم أفهم مبلغ الميزانية.\n' +
      'مثال: ارفع الميزانية إلى 600';

  } else if (raw === '/__invalid_natural_currency') {
    reply =
      '⚠️ حدد العملة التي تريدها.\n' +
      'مثال: اجعل العملة شيكل';

  } else if (raw === '/__invalid_natural_threshold') {
    reply =
      '⚠️ حدد نسبة التنبيه.\n' +
      'مثال: غير حد التنبيه إلى 20';

  } else if (raw === '/__invalid_natural_category') {
    reply =
      '⚠️ لم أستطع فهم إضافة التصنيف.\n\n' +
      'استخدم مثلًا:\n' +
      'ضيف تصنيف جديد اسمه مواصلات والكلمات المفتاحية لها تكسي، باص\n\n' +
      'أو:\n' +
      '/category_add مواصلات | تكسي، باص';

  } else if (['settings', 'menu', 'help', ''].includes(command)) {
    op = 'menu';
    reply = helpReply();

  } else if (command === 'budget') {
    const n = Number(arg);

    if (!Number.isFinite(n) || n <= 0) {
      reply = 'اكتب ميزانية صحيحة. مثال: /budget 500';
    } else {
      op = 'setting';
      key = 'monthly_budget_ils';
      value = String(n);
      description = 'Monthly budget in selected currency';

      reply =
        '✅ تم تغيير الميزانية إلى ' +
        n + ' ' + (settings.currency || 'ILS');
    }

  } else if (command === 'currency') {
    const v = normalizeCurrency(arg);

    if (!/^[A-Z]{3}$/.test(v)) {
      reply =
        '⚠️ اكتب اسم العملة أو رمزها.\n' +
        'أمثلة: شيكل، دولار، دينار، يورو\n' +
        '/currency ILS';
    } else {
      op = 'setting';
      key = 'currency';
      value = v;
      description = 'Currency code';

      const currencyNames = {
        ILS: 'الشيكل',
        USD: 'الدولار',
        JOD: 'الدينار الأردني',
        EUR: 'اليورو'
      };

      reply =
        '✅ تم تغيير العملة إلى ' +
        (currencyNames[v] || v) +
        ' (' + v + ').';
    }

  } else if (command === 'threshold') {
    const n = Number(arg);

    if (!Number.isFinite(n) || n < 1 || n > 1000) {
      reply = 'النسبة لازم تكون بين 1 و1000. مثال: /threshold 80';
    } else {
      op = 'setting';
      key = 'budget_alert_threshold_percent';
      value = String(n);
      description = 'Budget alert threshold percent';

      reply = '✅ تم تغيير نسبة التنبيه إلى ' + n + '%';
    }

  } else if (command === 'weekly' || command === 'monthly') {
    const v = arg.toLowerCase();

    if (
      ![
        'on', 'off', 'true', 'false',
        'تشغيل', 'إيقاف', 'تفعيل', 'تعطيل'
      ].includes(v)
    ) {
      reply = 'استخدم: /' + command + ' on أو /' + command + ' off';
    } else {
      op = 'setting';

      key = command === 'weekly'
        ? 'weekly_report_enabled'
        : 'monthly_report_enabled';

      value = [
        'on', 'true', 'تشغيل', 'تفعيل'
      ].includes(v) ? 'true' : 'false';

      description = command === 'weekly'
        ? 'Enable weekly report'
        : 'Enable monthly report';

      reply =
        '✅ ' +
        (command === 'weekly'
          ? 'التقرير الأسبوعي'
          : 'التقرير الشهري') +
        ' ' +
        (value === 'true' ? 'مفعّل' : 'متوقف');
    }

  } else if (command === 'category_add') {
    const parts = arg.split('|').map(clean);

    if (parts.length < 2 || !parts[0] || !parts[1]) {
      reply =
        'استخدم:\n' +
        '/category_add اسم التصنيف | كلمة1، كلمة2';

    } else if (
      cats.some(c =>
        clean(c.category_name).toLowerCase() ===
        parts[0].toLowerCase()
      )
    ) {
      reply = '⚠️ هذا التصنيف موجود مسبقًا.';

    } else {
      let max = 0;

      for (const c of cats) {
        const mm = normalizeId(c.category_id).match(/^C(\d+)$/);

        if (mm) {
          max = Math.max(max, Number(mm[1]));
        }
      }

      category_id = 'C' + String(max + 1).padStart(2, '0');
      category_name = parts[0];
      keywords = parseKeywords(parts.slice(1).join(' | '));
      enabled = 'TRUE';
      op = 'category_add';

      reply =
        '✅ تم طلب إضافة التصنيف ' +
        category_name + ' (' + category_id + ')';
    }

  } else if (
    [
      'category_name',
      'category_keywords',
      'category_toggle'
    ].includes(command)
  ) {
    const parts = arg.split('|').map(clean);

    if (command === 'category_toggle') {
      const tokens = clean(arg).split(/\s+/);
      category_id = normalizeId(tokens[0]);
      value = clean(tokens.slice(1).join(' ')).toLowerCase();
    } else {
      category_id = normalizeId(parts[0]);
    }

    const cat = cats.find(
      c => normalizeId(c.category_id) === category_id
    );

    if (!cat) {
      reply =
        '❌ لم أجد التصنيف ' + category_id +
        '. استخدم /categories لعرض القائمة.';

    } else if (command === 'category_name') {
      if (!parts[1]) {
        reply = 'استخدم: /category_name C11 | الاسم الجديد';
      } else {
        category_name = parts.slice(1).join(' | ');
        keywords = clean(cat.keywords || '');
        enabled = String(cat.enabled ?? 'TRUE');
        op = 'category_update';

        reply =
          '✅ تم طلب تغيير اسم ' + category_id +
          ' إلى ' + category_name;
      }

    } else if (command === 'category_keywords') {
      if (!parts[1]) {
        reply = 'استخدم: /category_keywords C11 | كلمة1، كلمة2';
      } else {
        category_name = clean(cat.category_name || '');
        keywords = parseKeywords(parts.slice(1).join(' | '));
        enabled = String(cat.enabled ?? 'TRUE');
        op = 'category_update';

        reply = '✅ تم طلب تحديث كلمات التصنيف ' + category_id;
      }

    } else {
      const v = value;

      if (
        !['on', 'off', 'true', 'false', 'تفعيل', 'تعطيل'].includes(v)
      ) {
        reply =
          'استخدم: /category_toggle C11 on أو /category_toggle C11 off';
      } else {
        category_name = clean(cat.category_name || '');
        keywords = clean(cat.keywords || '');

        enabled = ['on', 'true', 'تفعيل'].includes(v)
          ? 'TRUE'
          : 'FALSE';

        op = 'category_update';

        reply =
          '✅ التصنيف ' + category_name + ' ' +
          (enabled === 'TRUE' ? 'مفعّل' : 'معطّل');
      }
    }

  } else if (command === 'categories') {
    op = 'categories';
    reply = categoriesReply();

  } else {
    reply =
      '❓ الأمر غير معروف.\n' +
      'أرسل /settings لعرض الأوامر والأمثلة.';
  }
}

return [{
  json: {
    ...ctl,
    op,
    key,
    value,
    description,
    category_id,
    category_name,
    keywords,
    enabled,
    reply,
    updated_at: new Date().toISOString()
  }
}];

const s = Object.fromEntries($input.all().map(x => [String(x.json.key || '').trim(), x.json.value]));
const configured = String(s.authorized_telegram_user_id || '').trim();
const ctl = $('Control Router').first().json._control;
const fromId = String(ctl.fromId || '').trim();
const allowed = fromId !== '' && configured !== '' && !configured.includes('REPLACE_WITH') && fromId === configured;
return [{ json: { allowed, fromId, chatId: String(ctl.chatId || '') }, pairedItem: { item: 0 } }];

