const uid = String(ctl.fromId || '');
const settings = Object.fromEntries($('Read Settings').all().map(x => [String(x.json.key || '').trim(), x.json.value]));
const cur = String(settings.currency || 'ILS');
const budget = Number(settings.monthly_budget_ils || 300);
const rows = $input.all().map(x => x.json).filter(r => String(r.expense_id || '').trim());
const isActive = r => String(r.status || 'active').trim() === 'active';
const mine = rows.filter(r => isActive(r) && (!String(r.user_id || '').trim() || String(r.user_id).trim() === uid));
if (!mine.length) return [{ json: { hasUndo: false, reply: 'ما في مصروف مسجّل أقدر أتراجع عنه.' } }];
const ts = r => Date.parse(r.created_at || '') || 0;
let last = mine[0];
for (const r of mine) { if (ts(r) >= ts(last)) last = r; }
const mid = String(last.telegram_message_id || '').trim();
const batch = mid ? mine.filter(r => String(r.telegram_message_id || '').trim() === mid) : [last];
const ids = new Set(batch.map(r => r.expense_id));
const amt = r => Number(r.amount_ils || r.amount || 0);
const undone = batch.reduce((s, r) => s + amt(r), 0);
const mk = String(last.month_key || '').slice(0, 7);
const monthTotal = rows.filter(r => isActive(r) && !ids.has(r.expense_id) && String(r.month_key || '').slice(0, 7) === mk).reduce((s, r) => s + amt(r), 0);
const remaining = budget - monthTotal;
const reply = [
  '↩️ تم التراجع عن آخر تسجيل',
  ...batch.map(r => `🗑️ ${r.item}: ${amt(r)} ${cur}`),
  `💵 المجموع الملغي: ${undone} ${cur}`,
  `📊 مصاريف الشهر الآن: ${monthTotal} ${cur}`,
  remaining >= 0 ? `🟢 ضايلك: ${remaining} ${cur}` : `🔴 متجاوز الميزانية بـ ${Math.abs(remaining)} ${cur}`
].join('\n');
const updated_at = new Date().toISOString();
return batch.map(r => ({ json: { hasUndo: true, expense_id: r.expense_id, updated_at, reply } }));

const ctl = $('Control Router').first().json._control;
const text = String(ctl.text || '');
const settings = Object.fromEntries($('Read Settings').all().map(x => [String(x.json.key || '').trim(), x.json.value]));
const cur = String(settings.currency || 'ILS');
const budget = Number(settings.monthly_budget_ils || 300);
const tz = String(settings.timezone || 'Asia/Gaza');
const today = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
let mode = 'month';
if (/اليوم/.test(text)) mode = 'day';
else if (/(الاسبوع|الأسبوع|اسبوع|أسبوع)/.test(text)) mode = 'week';
const label = mode === 'day' ? 'اليوم' : (mode === 'week' ? 'آخر 7 أيام' : 'هالشهر');
const dayMs = 24 * 60 * 60 * 1000;
const startWeek = new Date(new Date(today + 'T00:00:00Z').getTime() - 6 * dayMs).toISOString().slice(0, 10);
const rows = $input.all().map(x => x.json).filter(r => String(r.expense_id || '').trim() && String(r.status || 'active').trim() === 'active');
const inRange = r => {
  const d = String(r.expense_date || '').slice(0, 10);
  if (mode === 'day') return d === today;
  if (mode === 'week') return d >= startWeek && d <= today;
  return String(r.month_key || r.expense_date || '').slice(0, 7) === today.slice(0, 7);
};
const act = rows.filter(inRange);
if (!act.length) return [{ json: { reply: `ما في مصاريف مسجّلة ${label} لسا.` } }];
const amt = r => Number(r.amount_ils || r.amount || 0);
const total = act.reduce((s, r) => s + amt(r), 0);
const fmtN = v => Number.isInteger(v) ? String(v) : v.toFixed(2);
const cats = {};
const items = {};
for (const r of act) {
  const c = String(r.category || 'أخرى').trim();
  cats[c] = (cats[c] || 0) + amt(r);
  const it = String(r.item || '').trim();
  if (it) { items[it] = items[it] || { sum: 0, n: 0 }; items[it].sum += amt(r); items[it].n += 1; }
}
const catList = Object.entries(cats).sort((a, b) => b[1] - a[1]);
const itemList = Object.entries(items).sort((a, b) => b[1].sum - a[1].sum).slice(0, 5);
const lines = [`📈 وين بتروح مصاريفك ${label}`, `💸 المجموع: ${fmtN(total)} ${cur} (${act.length} مصروف)`, '', '📂 حسب الفئة:'];
for (const [c, v] of catList.slice(0, 6)) {
  const pct = Math.round(v / total * 100);
  lines.push(`${'█'.repeat(Math.max(1, Math.round(pct / 10)))} ${c}: ${fmtN(v)} ${cur} (${pct}%)`);
}
lines.push('', '🛍️ أكثر أغراض بتصرف عليها:');
itemList.forEach(([it, o], i) => lines.push(`${i + 1}. ${it}: ${fmtN(o.sum)} ${cur}${o.n > 1 ? ' (' + o.n + ' مرات)' : ''}`));
if (mode === 'month') {
  const dayNum = Number(today.slice(8, 10)) || 1;
  const y = Number(today.slice(0, 4)); const m = Number(today.slice(5, 7));
  const dim = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const avg = total / dayNum;
  const proj = avg * dim;
  lines.push('', `📊 استخدمت ${Math.round(total / budget * 100)}% من ميزانيتك (${fmtN(budget)} ${cur})`);
  lines.push(`📅 معدّلك اليومي: ${fmtN(Math.round(avg * 100) / 100)} ${cur}`);
  lines.push(proj > budget ? `⚠️ بهالمعدّل رح توصل نهاية الشهر لحوالي ${fmtN(Math.round(proj))} ${cur} — أعلى من الميزانية` : `🟢 بهالمعدّل رح توصل نهاية الشهر لحوالي ${fmtN(Math.round(proj))} ${cur} — ضمن الميزانية`);
}
lines.push('', `💡 أكثر شي بتصرف عليه: ${catList[0][0]} (${Math.round(catList[0][1] / total * 100)}%)`);
return [{ json: { reply: lines.join('\n') } }];
